#!/usr/bin/env python3
"""
setup_project.py - TeamBoard v2.0 Enterprise Project Packager & Bootstrapper

Usage:
    python setup_project.py               # Package current source tree into project.zip
    python setup_project.py --pack        # Package release archive with clean manifest
    python setup_project.py --generate    # Generate/extract clean project tree to ./teamboard
    python setup_project.py --info        # Display project statistics, routes & components
    python setup_project.py --verify      # Verify schema, configuration & dependencies
    python setup_project.py --sync        # Sync embedded templates from active source tree
"""

