def resolve_source_dir() -> str:
    if os.path.isdir(DEFAULT_SOURCE_DIR):
        return DEFAULT_SOURCE_DIR
    if os.path.isdir(FALLBACK_SOURCE_DIR):
        return FALLBACK_SOURCE_DIR
    return FALLBACK_SOURCE_DIR

def get_live_files(source_dir: str) -> Dict[str, str]:
    collected: Dict[str, str] = {}
    if not os.path.isdir(source_dir):
        return EMBEDDED_FILES

    for dirpath, dirnames, filenames in os.walk(source_dir):
        dirnames[:] = [d for d in dirnames if d not in EXCLUDE_DIRS]
        for f in filenames:
            if f in EXCLUDE_FILES or f.endswith(".tsbuildinfo"):
                continue
            full_path = os.path.join(dirpath, f)
            rel_path = os.path.relpath(full_path, source_dir).replace("\\", "/")
            try:
                with open(full_path, "r", encoding="utf-8") as fh:
                    collected[rel_path] = fh.read()
            except (UnicodeDecodeError, PermissionError):
                pass
    return collected

def package_project(source_dir: str = None, output_zip: str = ZIP_NAME):
    source_dir = source_dir or resolve_source_dir()
    print("=" * 65)
    print("  TEAMBOARD ENTERPRISE PACKAGER (v2.0)")
    print("=" * 65)
    print(f"[*] Locating source tree at: '{source_dir}'...")

    files = get_live_files(source_dir)
    print(f"[*] Found {len(files)} source files to bundle.")

    total_uncompressed = 0
    with zipfile.ZipFile(output_zip, "w", zipfile.ZIP_DEFLATED) as zf:
        # Include teamboard app files
        for rel_path, content in sorted(files.items()):
            arcname = os.path.join("teamboard", rel_path)
            content_bytes = content.encode("utf-8")
            total_uncompressed += len(content_bytes)
            zf.writestr(arcname, content_bytes)

        # Include root documentation and screenshots if available
        for doc_file in ["README.md", "teamboard_qa_audit_report.md"]:
            if os.path.isfile(doc_file):
                zf.write(doc_file, doc_file)
                total_uncompressed += os.path.getsize(doc_file)

        screenshots_dir = os.path.join("docs", "screenshots")
        if os.path.isdir(screenshots_dir):
            for s in sorted(os.listdir(screenshots_dir)):
                s_path = os.path.join(screenshots_dir, s)
                if os.path.isfile(s_path):
                    zf.write(s_path, os.path.join("docs", "screenshots", s))
                    total_uncompressed += os.path.getsize(s_path)

    zip_size = os.path.getsize(output_zip)
    ratio = (1.0 - (zip_size / total_uncompressed)) * 100 if total_uncompressed > 0 else 0

    print(f"[+] Archive created successfully: '{output_zip}'")
    print(f"    - Uncompressed: {total_uncompressed / 1024:.1f} KB")
    print(f"    - Compressed:   {zip_size / 1024:.1f} KB (Saved {ratio:.1f}%)")
    print("=" * 65)

def generate_project(target_dir: str = "teamboard", force: bool = False):
    print("=" * 65)
    print("  TEAMBOARD STANDALONE GENERATOR")
    print("=" * 65)
    print(f"[*] Extracting project tree into: '{target_dir}'...")

    if os.path.exists(target_dir) and not force:
        print(f"[!] Warning: Target directory '{target_dir}' already exists.")
        choice = input("    Overwrite existing files? (y/N): ").strip().lower()
        if choice != "y":
            print("[x] Operation cancelled.")
            return

    count = 0
    for rel_path, content in EMBEDDED_FILES.items():
        full_path = os.path.join(target_dir, rel_path)
        os.makedirs(os.path.dirname(full_path), exist_ok=True)
        with open(full_path, "w", encoding="utf-8", newline="\n") as fh:
            fh.write(content)
        count += 1

    print(f"[+] Successfully generated {count} files into '{target_dir}'!")
    print("\nNext steps:")
    print(f"  cd {target_dir}")
    print("  npm install")
    print("  npx prisma db push")
    print("  npm run dev")
    print("=" * 65)

def show_info(source_dir: str = None):
    source_dir = source_dir or resolve_source_dir()
    files = get_live_files(source_dir)

    components = [f for f in files if f.startswith("src/components/")]
    routes = [f for f in files if f.startswith("src/app/api/")]
    pages = [f for f in files if f.startswith("src/app/") and f.endswith("page.tsx")]
    scripts = [f for f in files if f.startswith("scripts/")]

    total_lines = sum(len(content.splitlines()) for content in files.values())

    print("=" * 65)
    print("  TEAMBOARD ARCHITECTURE & INVENTORY INFO")
    print("=" * 65)
    print(f"Active Source Directory: {source_dir}")
    print(f"Total Source Files:      {len(files)}")
    print(f"Total Lines of Code:     {total_lines:,} LOC")
    print("-" * 65)
    print(f"React Components:        {len(components)} files")
    for c in sorted(components)[:8]:
        print(f"  - {c}")
    if len(components) > 8:
        print(f"  ... and {len(components) - 8} more components")
    print("-" * 65)
    print(f"REST API Route Handlers: {len(routes)} endpoints")
    for r in sorted(routes):
        print(f"  - {r}")
    print("-" * 65)
    print(f"Next.js 14 App Pages:    {len(pages)} pages")
    for p in sorted(pages):
        print(f"  - {p}")
    print("-" * 65)
    print(f"Automation & QA Scripts: {len(scripts)} scripts")
    for s in sorted(scripts):
        print(f"  - {s}")
    print("=" * 65)

